const D = { density:.55, energy:.6, hue:300, speed:1, scale:1, x:.5, y:.5, glow:.6, haze:.6, style:'neon', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return s - Math.floor(s); };
const u = Math.min(width, height);
const st = P.style;
const mono = st==='noir';
const laser = st==='laser';
const uv = st==='uv';
const h = P.hue;
const lightCol = (i)=>{ // returns [hue,sat,bri]
  if (mono) return [0,0,100];
  if (uv) return (i%2===0)?[282,80,100]:[186,85,100];
  if (laser) return [(h+i*47)%360,95,100];
  return [(h+K.section*38+i*31)%360,90,100];
};
const key = width+'x'+height+'|'+P.seed+'|'+st;
if (S.key !== key) {
  S.key = key;
  const g = createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100);
  g.noStroke();
  const floorY = height*0.72;
  // back wall gradient (dark)
  for (let i=0;i<80;i++){ const t=i/80, y=t*floorY;
    if (mono) g.fill(0,0,5+t*7);
    else if (uv) g.fill(270,40,4+t*8);
    else g.fill(h-30, 45, 4+t*9);
    g.rect(0,y,width,floorY/80+1);
  }
  // floor
  for (let i=0;i<40;i++){ const t=i/40, y=floorY+t*(height-floorY);
    if (mono) g.fill(0,0,8-t*5);
    else g.fill(h-20,35,10-t*7);
    g.rect(0,y,width,(height-floorY)/40+1);
  }
  // floor perspective lines
  g.stroke(mono?0:h, mono?0:30, mono?18:16, 40); g.strokeWeight(1);
  const vx=width*0.5;
  for(let i=-6;i<=6;i++){ const fxp=vx+i*width*0.14; g.line(vx,floorY,fxp,height); }
  for(let r=1;r<=4;r++){ const yy=floorY+(height-floorY)*(r/4)*(r/4); g.line(0,yy,width,yy); }
  g.noStroke();
  // truss bar
  g.fill(0,0,mono?14:10); g.rect(0,height*0.10,width,u*0.02);
  S.buf=g; S.floorY=floorY;
  // beams anchored on truss
  const nB=Math.floor(3+P.density*7);
  S.beam=[]; for(let i=0;i<nB;i++) S.beam.push({ax:(0.12+0.76*(i/(nB-1||1)))*1,base:(fr(i)*6.28),swing:0.5+fr(i+3)*0.8,rate:0.4+fr(i+5)*0.7,ph:fr(i+7)*6.28});
  // crowd heads
  const nC=Math.floor(12+P.density*34);
  S.crowd=[]; for(let i=0;i<nC;i++) S.crowd.push({x:fr(i+20)*width,z:fr(i+21),ph:fr(i+22)*6.28,w:0.7+fr(i+23)*0.6});
  S.crowd.sort((a,b)=>a.z-b.z);
  // mirror-ball speckles
  const nS=Math.floor(30+P.density*70);
  S.spk=[]; for(let i=0;i<nS;i++) S.spk.push({a:fr(i+50)*6.28,rad:fr(i+51),y:fr(i+52)*0.6,r:1+fr(i+53)*2.5,ph:fr(i+54)*6.28});
  // haze blobs
  S.haze=[]; for(let i=0;i<3;i++) S.haze.push({x:fr(i+70)*width,y:height*(0.2+fr(i+71)*0.3),r:u*(0.3+fr(i+72)*0.25),spd:0.2+fr(i+73)*0.3,ph:fr(i+74)*6.28});
}
image(S.buf,0,0);
const sc=P.scale, T=K.t, glow=P.glow*(0.6+A.rms), en=P.energy, floorY=S.floorY;
const trussY=height*0.11;
// haze drift (real-time floor)
push(); blendMode(ADD);
for(const z of S.haze){ const xx=((z.x+T*z.spd*40)%(width+z.r*2))-z.r, yy=z.y+Math.sin(T*0.25+z.ph)*u*0.05;
  fill(mono?0:h-10, mono?0:30, mono?30:40, (6+P.haze*10)*(0.7+glow*0.5));
  ellipse(xx,yy,z.r*(1.4+K.swell*0.2),z.r*0.8);
}
blendMode(BLEND); pop();
// light beams (cones) — sweep continuous + step target per beat
push(); blendMode(ADD);
for(let i=0;i<S.beam.length;i++){ const b=S.beam[i], ax=b.ax*width,
  stepTarget=((Math.floor(K.beat*P.speed)+i*3)%7-3)/3,
  ang=Math.sin(T*b.rate*0.6+b.ph)*b.swing*0.5 + stepTarget*0.5,
  len=height*0.95, spread=u*0.05*sc*(1+en*0.6),
  col=lightCol(i), a=(mono?14:11)*(0.5+en)*(0.7+glow*0.6)+K.pulse*en*8;
  const tx=ax+Math.sin(ang)*width*0.5, ty=trussY+len;
  if (laser){ stroke(col[0],col[1],col[2],40+en*40+K.pulse*30); strokeWeight(1.5+en*1.5);
    line(ax,trussY,tx,ty); noStroke();
  } else {
    fill(col[0],col[1]*0.9,col[2],a);
    triangle(ax-spread*0.2,trussY,tx-spread,ty,tx+spread,ty);
    fill(col[0],col[1],col[2],60+glow*30); ellipse(ax,trussY,u*0.02,u*0.02);
  }
}
blendMode(BLEND); pop();
// mirror-ball speckles rotating
push(); blendMode(ADD);
const mbx=P.x*width, mby=height*0.16;
for(const s of S.spk){ const ang=s.a+T*0.3, xx=mbx+Math.cos(ang)*width*0.5*s.rad, yy=mby+s.y*height*0.7+Math.sin(ang*1.3+s.ph)*u*0.02,
  tw=0.5+0.5*Math.sin(T*2+s.ph), col=lightCol((s.a*3)|0);
  fill(mono?0:col[0],mono?0:60,100,(20+40*tw)*(0.5+en)+K.pulse*20);
  const rr=s.r*sc*(0.6+tw); ellipse(xx,yy,rr,rr);
}
blendMode(BLEND); pop();
// crowd silhouettes bobbing (real-time + swell)
for(const c of S.crowd){ const depth=c.z, cy=floorY+ (1-depth)*(height-floorY)*0.15,
  bob=Math.sin(T*2.2*P.speed+c.ph)*u*0.012*(1+A.lowmid)+K.swell*u*0.01,
  hh=u*(0.08+depth*0.10)*c.w*sc, hw=hh*0.5,
  bri=mono?0:8+depth*6;
  noStroke(); fill(mono?0:h-20, mono?0:40, bri);
  const hx=c.x, hy=cy-bob;
  // shoulders
  ellipse(hx,hy+hh*0.5,hw*1.8,hh*0.7);
  // head
  ellipse(hx,hy,hw*0.7,hw*0.8);
  // arm hint up on strong beats
  if (K.pulse>0.5 && fr((c.x|0)+3)>0.5){ stroke(mono?0:h-20,mono?0:40,bri); strokeWeight(hw*0.25); noFill();
    line(hx,hy+hh*0.2,hx-hw*0.6,hy-hh*0.3); line(hx,hy+hh*0.2,hx+hw*0.6,hy-hh*0.3); noStroke(); }
}
// partial beat flash (bounded — never full-frame white)
const flash=K.pulse*en*(0.4+A.bass*0.6);
if (flash>0.02){ push(); blendMode(ADD);
  const col=lightCol(K.section|0);
  fill(mono?0:col[0], mono?0:40, mono?100:90, Math.min(26, flash*30));
  rect(0,0,width,height*0.5);
  blendMode(BLEND); pop();
}
